export class Node {
  constructor(name) { this.n = name; }
  name() { return this.n; }
}
export function pick(named) { return named ? new Node("a") : "none"; }
export const util = { tag: () => "pa" };
export class Point { constructor() { this.x = 3; } }
export function toGeo(p) { return { lat: p.x }; }
